    getResource(WIDGET_START_URL_ROOT);
    //
    // take off the resource bit
    //
    WIDGET_START_URL_ROOT = getRootUrl(WIDGET_START_URL_ROOT);
    post.releaseConnection();
    resource = "index.htm";
